<?php
require __DIR__.'/../config/koneksi.php'; require_admin();
$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try {
  if($action==='save'){
   $id=(int)($_POST['id']??0);$kode=trim($_POST['kode_produk']??'');$nama=trim($_POST['nama_produk']??'');$kat=(int)($_POST['id_kategori']??0);$modal=(float)($_POST['harga_modal']??-1);$jual=(float)($_POST['harga_jual']??-1);$stok=(int)($_POST['stok']??-1);$min=(int)($_POST['stok_minimum']??-1);
   if($kode===''||$nama===''||$modal<0||$jual<0||$stok<0||$min<0)throw new Exception('Lengkapi data dengan benar; nilai harga dan stok tidak boleh negatif.');
   if($id){$q=$pdo->prepare('UPDATE produk SET kode_produk=?,nama_produk=?,id_kategori=?,harga_modal=?,harga_jual=?,stok=?,stok_minimum=? WHERE id=?');$q->execute([$kode,$nama,$kat?:null,$modal,$jual,$stok,$min,$id]);}
   else{$q=$pdo->prepare('INSERT INTO produk(kode_produk,nama_produk,id_kategori,harga_modal,harga_jual,stok,stok_minimum) VALUES(?,?,?,?,?,?,?)');$q->execute([$kode,$nama,$kat?:null,$modal,$jual,$stok,$min]);}
   header('Location: produk.php?ok=1');exit;
  }elseif($action==='delete'){$q=$pdo->prepare('DELETE FROM produk WHERE id=?');$q->execute([(int)$_POST['id']]);header('Location: produk.php?deleted=1');exit;}
 }catch(Throwable $ex){$error=$ex instanceof PDOException?'Gagal menyimpan. Pastikan kode produk unik.':$ex->getMessage();}
}
if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM produk WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$cats=$pdo->query('SELECT * FROM kategori ORDER BY nama_kategori')->fetchAll();
$search=trim($_GET['q']??'');$cat=(int)($_GET['kategori']??0);$sql='SELECT p.*,k.nama_kategori FROM produk p LEFT JOIN kategori k ON k.id=p.id_kategori WHERE (p.nama_produk LIKE ? OR p.kode_produk LIKE ?)';$params=["%$search%","%$search%"];if($cat){$sql.=' AND p.id_kategori=?';$params[]=$cat;}$sql.=' ORDER BY p.id DESC';$q=$pdo->prepare($sql);$q->execute($params);$products=$q->fetchAll();
page_start('Manajemen Produk');
?>
<?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><?php if(isset($_GET['ok'])): ?><div class="alert alert-success">Produk berhasil disimpan.</div><?php endif; ?><?php if(isset($_GET['deleted'])): ?><div class="alert alert-success">Produk berhasil dihapus.</div><?php endif; ?>
<div class="row g-3"><div class="col-xl-4"><div class="panel-card"><div class="panel-heading"><h3><?= $edit?'Edit Produk':'Tambah Produk' ?></h3></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label class="form-label">Kode Produk</label><input class="form-control mb-3" name="kode_produk" required value="<?=e($edit['kode_produk']??'')?>"><label class="form-label">Nama Produk</label><input class="form-control mb-3" name="nama_produk" required value="<?=e($edit['nama_produk']??'')?>"><label class="form-label">Kategori</label><select class="form-select mb-3" name="id_kategori"><option value="">Tanpa kategori</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=($edit['id_kategori']??'')==$c['id']?'selected':''?>><?=e($c['nama_kategori'])?></option><?php endforeach; ?></select><div class="row"><div class="col-6"><label class="form-label">Harga Modal</label><input class="form-control mb-3" type="number" min="0" step="0.01" name="harga_modal" required value="<?=e($edit['harga_modal']??'0')?>"></div><div class="col-6"><label class="form-label">Harga Jual</label><input class="form-control mb-3" type="number" min="0" step="0.01" name="harga_jual" required value="<?=e($edit['harga_jual']??'0')?>"></div></div><div class="row"><div class="col-6"><label class="form-label">Stok</label><input class="form-control mb-3" type="number" min="0" name="stok" required value="<?=e($edit['stok']??'0')?>"></div><div class="col-6"><label class="form-label">Stok Minimum</label><input class="form-control mb-3" type="number" min="0" name="stok_minimum" required value="<?=e($edit['stok_minimum']??'5')?>"></div></div><button class="btn btn-primary w-100"><i class="fa-solid fa-floppy-disk me-2"></i>Simpan Produk</button><?php if($edit): ?><a class="btn btn-outline-secondary w-100 mt-2" href="produk.php">Batal edit</a><?php endif; ?></form></div></div>
<div class="col-xl-8"><div class="panel-card"><form class="row g-2 mb-3"><div class="col-md-7"><input class="form-control" name="q" placeholder="Cari nama atau kode produk..." value="<?=e($search)?>"></div><div class="col-md-3"><select class="form-select" name="kategori"><option value="0">Semua kategori</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['nama_kategori'])?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Cari</button></div></form><div class="table-responsive"><table class="table modern-table"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?=e($p['nama_produk'])?></strong><small class="d-block muted"><?=e($p['kode_produk'])?></small></td><td><?=e($p['nama_kategori']??'-')?></td><td><?=rupiah($p['harga_jual'])?></td><td><?php if($p['stok']<=0): ?><span class="stock-badge danger">Habis</span><?php elseif($p['stok']<=$p['stok_minimum']): ?><span class="stock-badge warning"><?=number_format($p['stok'])?> · Menipis</span><?php else: ?><span class="stock-badge good"><?=number_format($p['stok'])?></span><?php endif; ?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$p['id']?>"><i class="fa-solid fa-pen"></i></a> <form method="post" class="d-inline" onsubmit="return confirm('Hapus produk ini?')" ><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm btn-outline-danger"><i class="fa-solid fa-trash"></i></button></form></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="5" class="text-center muted py-4">Produk tidak ditemukan.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
<?php page_end(); ?>
